Target: YOUR account only.
--]]
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer
local MyUserId = LocalPlayer.UserId

local Boxing = ReplicatedStorage:WaitForChild("Boxing")
local Remote = Boxing:WaitForChild("AdminPanelRemote")

local before = LocalPlayer:GetAttribute("Cash")
print("Cash before: " .. tostring(before))

local ok, result1, result2 = pcall(function()
    return Remote:InvokeServer("GiveYen", MyUserId, 10000)
end)

task.wait(0.5)
local after = LocalPlayer:GetAttribute("Cash")
print("Cash after: " .. tostring(after))
print("Client ok: " .. tostring(ok))
print("Result1: " .. tostring(result1))
print("Result2: " .. tostring(result2 or "nil"))

if after ~= before then
    print("VULNERABLE: Cash changed!")
else
    print("Secure: No change or server rejected.")
end

