--[[
Hajime Rising [ALPHA] â€” StatsRemote:ResetBuild Test
--]]
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local Remote = ReplicatedStorage:WaitForChild("Boxing"):WaitForChild("StatsRemote")

local stats = {"Stat_Power","Stat_Endurance","Stat_Stamina","Stat_Speed","Stat_Technique","Stat_Willpower","StatPointsRemaining"}
local before = {}
for _, s in ipairs(stats) do before[s] = LocalPlayer:GetAttribute(s) end

local ok, err = pcall(function()
    Remote:FireServer("ResetBuild")
end)

task.wait(0.5)
local changed = false
for _, s in ipairs(stats) do
    local after = LocalPlayer:GetAttribute(s)
    if after ~= before[s] then
        print(s .. ": " .. tostring(before[s]) .. " -> " .. tostring(after))
        changed = true
    end
end
print("Client ok: " .. tostring(ok))
if not ok then print("Error: " .. tostring(err)) end
if changed then print("VULNERABLE: Stats changed!") else print("Secure/No change.") end

