local REM = {}
for _, n in ipairs({"AdminPanelRemote","StatsRemote","TechniqueRemote","BoxingRemote","SparringRemote","SurvivalRemote","AtmRemote","GearRemote","LoadoutRemote","AvatarRemote"}) do
    REM[n] = Boxing:WaitForChild(n, true)
end

local function safeInvoke(remote, op, ...)
    if not remote or not remote:IsA("RemoteFunction") then return false, "bad remote" end
    local args = table.pack(...)
    return pcall(function() return remote:InvokeServer(op, table.unpack(args, 1, args.n)) end)
end
local function safeFire(remote, op, ...)
    if not remote or not remote:IsA("RemoteEvent") then return false, "bad remote" end
    local args = table.pack(...)
    return pcall(function() remote:FireServer(op, table.unpack(args, 1, args.n)) end)
end

local WATCH = {"Cash","StatPointsRemaining","AdminFly","AdminNoclip","AdminBTools","Stat_Power","Stat_Stamina"}
local function snapshot()
    local t = {}
    for _, n in ipairs(WATCH) do t[n] = LocalPlayer:GetAttribute(n) end
    return t
end
local function diff(before, after)
    local d = {}
    for n, v in pairs(after) do if before[n] ~= v then d[n] = {before[n], v} end end
    return d
end

