Instance.new("UICorner", snapBtn).CornerRadius = UDim.new(0,6)
snapBtn.MouseButton1Click:Connect(function()
    lastSnap = snapshot()
    l("[SNAPSHOT] Taken")
end)

local function run(name, remoteName, op, args, rType)
    local r = REM[remoteName]
    if not r then l(name .. ": remote missing") return end
    local before = lastSnap or snapshot()
    lastSnap = nil
    local cOk, cErr, sOk, sMsg
    if rType == "Function" then
        local ok, a, b = safeInvoke(r, op, table.unpack(args))
        cOk = ok; cErr = ok and nil or tostring(a); sOk = ok; sMsg = ok and tostring(a) or tostring(b or "")
    else
        local ok, e = safeFire(r, op, table.unpack(args))
        cOk = ok; cErr = ok and nil or tostring(e); sOk = ok; sMsg = ok and "fired" or tostring(e)
    end
    task.wait(0.4)
    local after = snapshot()
    local d = diff(before, after)
    local changed = next(d) ~= nil
    l(string.format("[%s] %s.%s -> client=%s server=%s changed=%s", name, remoteName, op, tostring(cOk), tostring(sOk), tostring(changed)))
    if #d > 0 then
        for k, pair in pairs(d) do l("  " .. k .. ": " .. tostring(pair[1]) .. " -> " .. tostring(pair[2])) end
    end
end

local y = 40
local function btn(text, remoteName, op, args, rType)
    local b = Instance.new("TextButton")
    b.Size = UDim2.new(0,150,0,30)
    b.Position = UDim2.new(0, 10 + ((y-40)//60)*165, 0, y + ((y-40)%60)*0)
    b.BackgroundColor3 = Color3.fromRGB(90,140,255)
    b.Text = text
    b.TextColor3 = Color3.new(1,1,1)
    b.TextSize = 12
    b.Font = Enum.Font.GothamBold
    b.Parent = main
    Instance.new("UICorner", b).CornerRadius = UDim.new(0,6)
    b.MouseButton1Click:Connect(function() run(text, remoteName, op, args, rType) end)
    y = y + 34
end

